-- =====================================================================
-- Importación de datos de teletrabajo desde "Teletrabajo 2026_14072026.xlsx"
-- y de roles/coordinadores desde "Listado WFH.xlsx".
--
-- El Excel de teletrabajo identifica a los empleados por "WD Nr" (número de
-- nómina), que NO es el oracle_emp_id de Postgres. Cada WD Nr se resolvió
-- consultando TIMERTASK_ES.templeados.emp_tel1 (que almacena el WD Number)
-- para obtener el emp_id real (= users.oracle_emp_id). El listado de
-- coordinadores identifica a las personas por email, resuelto contra
-- TIMERTASK_ES.templeados.emp_email. Cuando un WD Nr o email tenía más de
-- un emp_id en Oracle (registros históricos), se usó el activo
-- (emp_esempleado = 1 AND emp_fec_baja IS NULL).
--
-- 1) Actualiza has_wfh y wfh_days_allowance en la tabla users.
-- 2) Reemplaza los días concretos de teletrabajo de 2026 en
--    work_from_home_days por los marcados en el Excel (261 columnas de
--    fecha, una por cada día laborable de enero a diciembre de 2026).
-- 3) Marca como 'coordinator' a los responsables de "Listado WFH.xlsx" y
--    asigna coordinator_id a sus empleados (resuelto por oracle_emp_id,
--    no por UUID, para que funcione en cualquier base de datos destino).
--
-- Mapeo aplicado:
--   WFH = Yes / OS / Out  -> has_wfh = true
--   WFH = No              -> has_wfh = false
--   Días                  -> wfh_days_allowance
--   Celda de fecha = "1"  -> día de teletrabajo concreto (work_from_home_days)
--
-- Nota: se excluye la fila del Excel de teletrabajo con WD Nr = "1000NP"
-- (Administrador Único), que no tiene emp_tel1 en Oracle (es la cuenta de
-- sistema gestionada vía fallback_email, no vía oracle_emp_id). El rol
-- 'admin' no se toca en ningún caso desde este script.
-- =====================================================================

