-- 2c) Roles y coordinadores (fuente: "Listado WFH.xlsx"), resueltos por email
--     contra Oracle (emp_email) y aplicados via oracle_emp_id, NO por UUID,
--     para que el script funcione en cualquier base de datos destino.
--
-- Marca como 'coordinator' a los emails que aparecen en la columna
-- "Coordinador" del listado. No se asigna coordinator_id a los propios
-- coordinadores (el listado no especifica su responsable).
UPDATE users AS u
SET role = 'coordinator'
FROM (VALUES
  (23),
  (29),
  (43),
  (44),
  (92),
  (100),
  (163),
  (182),
  (240),
  (415)
) AS c(oracle_emp_id)
WHERE u.oracle_emp_id = c.oracle_emp_id;

-- Asigna coordinator_id a cada empleado listado, resolviendo el UUID del
-- coordinador dinámicamente por su oracle_emp_id.
UPDATE users AS u
SET coordinator_id = (
  SELECT id FROM users WHERE oracle_emp_id = p.coordinator_emp_id
)
FROM (VALUES
